entries.answer:
A kód futtatható, de több konkrét (biztonsági, megbízhatósági és karbantarthatósági) hiba van benne, és a jelenlegi formában nem tekinthető production‑readynek. A Flask dokumentációja szerint a beépített fejlesztői szervert nem érdemes éles környezetben használni, helyette production WSGI szerver javasolt.[1]

## Konkrét hibák
Az alábbiak tényleges problémák (nem ízlésbeli kérdések), amelyek hibás működéshez, félrevezető állapotjelentéshez vagy komoly biztonsági kockázathoz vezethetnek.[2][3]
- Hardcoded `SECRET_KEY` a forráskódban (titok kikerülhet VCS-ből, logból, buildből; kulcs-rotáció nehéz).[3][2]
- Hardcoded API-kulcs „fallback” értékek: ha nincs env var, akkor is „van kulcs”, így a `/health` hamisan egészségesnek jelzi a szolgáltatásokat, és a rendszer megpróbálhat érvénytelen kulccsal hívni.  
- Felesleges importok: `json`, `threading` (eredetileg), ami jelzi, hogy a fájl nincs rendben tartva és növeli a karbantartási hibák esélyét.  
- `perform_parallel_search` közös `results` dict-et ír több szálból lock nélkül (gyakorlati versenyhelyzet/inkonzisztencia kockázata).  
- A `concurrent.futures.wait(..., timeout=45)` után nincs kezelés arra, ha valamelyik future bent ragad/timeoutol (hiányos eredmények „néma” félresikerülése).  
- `/search` csak `request.form`-ot kezel; JSON body-t (tipikus API használat) nem, emiatt kliensoldali integráció könnyen hibára fut.  
- Külső API válaszoknál nincs egységes `raise_for_status()` és kontrollált hibaszöveg-korlátozás (a `response.text` visszaadása túl nagy lehet, és érzékeny adatot is tartalmazhat).  
- `index.html` template hiányában az `/` route 500-at dob (nincs fallback), ami telepítéskor gyakori üzemeltetési hiba.  
- `app.run(... threaded=True)` önmagában nem garantálja a stabil/hatékony éles futtatást; ehhez WSGI szerver javasolt.[1]

## Javított fájl
A kód alább egyetlen fájlban van, kommentek és docstringek nélkül, környezeti változókból konfigurálható, thread-safe gyűjtéssel, thread-local HTTP sessionnel, retry/pool beállításokkal és form+JSON bemenet támogatással.[3][1]

```python
import os
import time
import logging
import threading
import concurrent.futures
from datetime import datetime
from typing import Any, Dict, Optional, Tuple

import requests
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry

from flask import Flask, request, jsonify, render_template
from jinja2 import TemplateNotFound

PPLX_ENDPOINT = ""
EXA_ENDPOINT = ""
BRAVE_ENDPOINT = ""

DEFAULT_TIMEOUT_SECONDS = 30
DEFAULT_PARALLEL_TIMEOUT_SECONDS = 45
DEFAULT_MAX_QUERY_LENGTH = 500
DEFAULT_NUM_RESULTS = 10

_thread_local = threading.local()


def _get_env(name: str, default: Optional[str] = None) -> Optional[str]:
    value = os.environ.get(name)
    if value is None:
        return default
    value = value.strip()
    return value if value else default


def _build_session() -> requests.Session:
    s = requests.Session()
    retry = Retry(
        total=3,
        connect=3,
        read=3,
        status=3,
        backoff_factor=0.4,
        status_forcelist=(429, 500, 502, 503, 504),
        allowed_methods=frozenset({"GET", "POST"}),
        raise_on_status=False,
    )
    adapter = HTTPAdapter(
        max_retries=retry,
        pool_connections=64,
        pool_maxsize=64,
    )
    s.mount("https://", adapter)
    s.mount("http://", adapter)
    return s


def http_session() -> requests.Session:
    s = getattr(_thread_local, "session", None)
    if s is None:
        s = _build_session()
        _thread_local.session = s
    return s


def _safe_text(text: str, limit: int = 2000) -> str:
    if text is None:
        return ""
    if len(text) <= limit:
        return text
    return text[:limit] + "...(truncated)"


def search_perplexity(query: str, api_key: Optional[str], model: str, timeout: int) -> Dict[str, Any]:
    if not api_key:
        return {"success": False, "error": "Perplexity API kulcs nincs beállítva (PERPLEXITY_API_KEY)."}
    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}
    payload = {
        "model": model,
        "messages": [
            {
                "role": "system",
                "content": "Te egy szakértő kutató vagy. Adj átfogó, részletes és pontos választ a kérdésre. Használj aktuális információkat és hivatkozz forrásokra ahol lehetséges.",
            },
            {"role": "user", "content": query},
        ],
        "max_tokens": 4000,
        "temperature": 0.2,
        "top_p": 0.9,
        "stream": False,
    }
    try:
        r = http_session().post(PPLX_ENDPOINT, headers=headers, json=payload, timeout=timeout)
        if r.status_code != 200:
            return {"success": False, "error": f"Perplexity API hiba: {r.status_code} - {_safe_text(r.text)}"}
        data = r.json()
        choices = data.get("choices") or []
        if not choices:
            return {"success": False, "error": "Nem érkezett válasz a Perplexity AI-tól (choices üres)."}
        msg = (choices[0].get("message") or {}).get("content")
        if not msg:
            return {"success": False, "error": "Nem érkezett értelmezhető tartalom a Perplexity AI-tól."}
        return {"success": True, "unified_response": msg, "raw_response": data}
    except requests.exceptions.RequestException as e:
        return {"success": False, "error": f"Perplexity kapcsolódási hiba: {str(e)}"}
    except ValueError as e:
        return {"success": False, "error": f"Perplexity JSON feldolgozási hiba: {str(e)}"}


def search_exa(query: str, api_key: Optional[str], timeout: int, num_results: int) -> Dict[str, Any]:
    if not api_key:
        return {"success": False, "error": "Exa API kulcs nincs beállítva (EXA_API_KEY)."}
    headers = {"x-api-key": api_key, "Content-Type": "application/json"}
    payload = {
        "query": query,
        "type": "auto",
        "useAutoprompt": True,
        "numResults": num_results,
        "contents": {
            "summary": {"query": f"Összegzés: {query}"},
            "highlights": {"query": f"Kiemelt információk: {query}", "numSentences": 3},
        },
    }
    try:
        r = http_session().post(EXA_ENDPOINT, headers=headers, json=payload, timeout=timeout)
        if r.status_code != 200:
            return {"success": False, "error": f"Exa API hiba: {r.status_code} - {_safe_text(r.text)}"}
        return {"success": True, "response": r.json()}
    except requests.exceptions.RequestException as e:
        return {"success": False, "error": f"Exa kapcsolódási hiba: {str(e)}"}
    except ValueError as e:
        return {"success": False, "error": f"Exa JSON feldolgozási hiba: {str(e)}"}


def search_brave(query: str, api_key: Optional[str], timeout: int, num_results: int) -> Dict[str, Any]:
    if not api_key:
        return {"success": False, "error": "Brave API kulcs nincs beállítva (BRAVE_API_KEY)."}
    headers = {"X-Subscription-Token": api_key, "Accept": "application/json"}
    params = {
        "q": query,
        "country": "HU",
        "search_lang": "hu",
        "ui_lang": "hu",
        "count": num_results,
        "offset": 0,
        "safesearch": "moderate",
        "freshness": "pw",
        "text_decorations": True,
        "spellcheck": True,
        "result_filter": "web,news",
    }
    try:
        r = http_session().get(BRAVE_ENDPOINT, headers=headers, params=params, timeout=timeout)
        if r.status_code != 200:
            return {"success": False, "error": f"Brave API hiba: {r.status_code} - {_safe_text(r.text)}"}
        return {"success": True, "response": r.json()}
    except requests.exceptions.RequestException as e:
        return {"success": False, "error": f"Brave kapcsolódási hiba: {str(e)}"}
    except ValueError as e:
        return {"success": False, "error": f"Brave JSON feldolgozási hiba: {str(e)}"}


def perform_parallel_search(
    query: str,
    pplx_key: Optional[str],
    exa_key: Optional[str],
    brave_key: Optional[str],
    pplx_model: str,
    timeout: int,
    parallel_timeout: int,
    num_results: int,
    logger: logging.Logger,
) -> Dict[str, Any]:
    start = time.time()
    results: Dict[str, Any] = {}
    lock = threading.Lock()

    def set_result(name: str, value: Dict[str, Any]) -> None:
        with lock:
            results[name] = value

    tasks: Dict[str, Tuple[Any, Tuple[Any, ...]]] = {
        "perplexity": (search_perplexity, (query, pplx_key, pplx_model, timeout)),
        "exa": (search_exa, (query, exa_key, timeout, num_results)),
        "brave": (search_brave, (query, brave_key, timeout, num_results)),
    }

    with concurrent.futures.ThreadPoolExecutor(max_workers=3) as ex:
        future_map: Dict[concurrent.futures.Future, str] = {}
        for name, (fn, args) in tasks.items():
            future_map[ex.submit(fn, *args)] = name

        done = set()
        try:
            for fut in concurrent.futures.as_completed(future_map, timeout=parallel_timeout):
                name = future_map[fut]
                done.add(fut)
                try:
                    set_result(name, fut.result())
                except Exception as e:
                    set_result(name, {"success": False, "error": str(e)})
        except concurrent.futures.TimeoutError:
            for fut, name in future_map.items():
                if fut not in done:
                    fut.cancel()
                    set_result(name, {"success": False, "error": "Időtúllépés a párhuzamos keresésben."})

    duration = time.time() - start
    successful_sources = sum(1 for v in results.values() if isinstance(v, dict) and v.get("success") is True)
    total_sources = 3

    logger.info("Kereses befejezve: %.2f masodperc, %d/%d forras sikeres", duration, successful_sources, total_sources)

    results["search_metadata"] = {
        "query": query,
        "search_duration": duration,
        "successful_sources": successful_sources,
        "total_sources": total_sources,
        "timestamp": datetime.now().isoformat(),
    }
    return results


def create_app() -> Flask:
    app = Flask(__name__)

    logging.basicConfig(
        level=_get_env("LOG_LEVEL", "INFO"),
        format="%(asctime)s %(levelname)s %(name)s %(message)s",
    )
    logger = logging.getLogger("aura_search")

    secret_key = _get_env("FLASK_SECRET_KEY") or _get_env("SECRET_KEY")
    if not secret_key:
        raise RuntimeError("SECRET_KEY nincs beallitva. Add meg FLASK_SECRET_KEY vagy SECRET_KEY kornyezeti valtozokent.")
    app.config["SECRET_KEY"] = secret_key

    app.config["PPLX_API_KEY"] = _get_env("PERPLEXITY_API_KEY")
    app.config["EXA_API_KEY"] = _get_env("EXA_API_KEY")
    app.config["BRAVE_API_KEY"] = _get_env("BRAVE_API_KEY")
    app.config["PPLX_MODEL"] = _get_env("PERPLEXITY_MODEL", "llama-3.1-sonar-large-128k-online")
    app.config["HTTP_TIMEOUT_SECONDS"] = int(_get_env("HTTP_TIMEOUT_SECONDS", str(DEFAULT_TIMEOUT_SECONDS)) or DEFAULT_TIMEOUT_SECONDS)
    app.config["PARALLEL_TIMEOUT_SECONDS"] = int(_get_env("PARALLEL_TIMEOUT_SECONDS", str(DEFAULT_PARALLEL_TIMEOUT_SECONDS)) or DEFAULT_PARALLEL_TIMEOUT_SECONDS)
    app.config["MAX_QUERY_LENGTH"] = int(_get_env("MAX_QUERY_LENGTH", str(DEFAULT_MAX_QUERY_LENGTH)) or DEFAULT_MAX_QUERY_LENGTH)
    app.config["NUM_RESULTS"] = int(_get_env("NUM_RESULTS", str(DEFAULT_NUM_RESULTS)) or DEFAULT_NUM_RESULTS)

    @app.get("/")
    def index():
        try:
            return render_template("index.html")
        except TemplateNotFound:
            return (
                "<!doctype html><html><head><meta charset='utf-8'><title>Aura Search</title></head>"
                "<body><h1>Aura Search Engine</h1><p>A template (index.html) hianyzik.</p></body></html>",
                200,
                {"Content-Type": "text/html; charset=utf-8"},
            )

    @app.post("/search")
    def search():
        query = ""
        if request.is_json:
            body = request.get_json(silent=True) or {}
            if isinstance(body, dict):
                query = str(body.get("query", "")).strip()
        if not query:
            query = str(request.form.get("query", "")).strip()

        if not query:
            return jsonify({"error": "Kérem adjon meg egy keresesi kifejezest!"}), 400

        max_len = app.config["MAX_QUERY_LENGTH"]
        if len(query) > max_len:
            return jsonify({"error": f"A keresesi kifejezes tul hosszu (maximum {max_len} karakter)!"}), 400

        logger.info("Uj kereses indult: %s", query)

        results = perform_parallel_search(
            query=query,
            pplx_key=app.config["PPLX_API_KEY"],
            exa_key=app.config["EXA_API_KEY"],
            brave_key=app.config["BRAVE_API_KEY"],
            pplx_model=app.config["PPLX_MODEL"],
            timeout=app.config["HTTP_TIMEOUT_SECONDS"],
            parallel_timeout=app.config["PARALLEL_TIMEOUT_SECONDS"],
            num_results=app.config["NUM_RESULTS"],
            logger=logger,
        )

        meta = results.get("search_metadata", {}) if isinstance(results.get("search_metadata"), dict) else {}
        response_data = {
            "query": query,
            "timestamp": datetime.now().isoformat(),
            "search_duration": meta.get("search_duration", 0),
            "successful_sources": meta.get("successful_sources", 0),
            "total_sources": meta.get("total_sources", 3),
            "perplexity": results.get("perplexity", {"success": False, "error": "Nem elerheto"}),
            "exa": results.get("exa", {"success": False, "error": "Nem elerheto"}),
            "brave": results.get("brave", {"success": False, "error": "Nem elerheto"}),
        }
        return jsonify(response_data), 200

    @app.get("/health")
    def health_check():
        return jsonify(
            {
                "status": "healthy",
                "timestamp": datetime.now().isoformat(),
                "version": "1.1.0",
                "services": {
                    "perplexity": bool(app.config.get("PPLX_API_KEY")),
                    "exa": bool(app.config.get("EXA_API_KEY")),
                    "brave": bool(app.config.get("BRAVE_API_KEY")),
                },
            }
        )

    @app.get("/api/test")
    def api_test():
        return jsonify(
            {
                "message": "Aura Search Engine API mukodik!",
                "timestamp": datetime.now().isoformat(),
                "endpoints": {"search": "/search (POST)", "health": "/health (GET)", "home": "/ (GET)"},
            }
        )

    @app.errorhandler(404)
    def not_found(_error):
        return jsonify({"error": "Az oldal nem talalhato", "status_code": 404}), 404

    @app.errorhandler(429)
    def rate_limit_error(_error):
        return jsonify({"error": "Tul sok keres. Kerem probalja ujra kesobb.", "status_code": 429}), 429

    @app.errorhandler(500)
    def internal_error(_error):
        return jsonify({"error": "Belso szerver hiba", "status_code": 500}), 500

    return app


app = create_app()

if __name__ == "__main__":
    log = logging.getLogger("aura_search")
    log.info("Aura Search Engine inditasa...")
    app.run(host=_get_env("HOST", "0.0.0.0"), port=int(_get_env("PORT", "5000") or 5000), debug=False, threaded=True)
